    "NON_PROVA": {
     "en": "APPROVAL EXPIRY IS NOT NON-RENEWAL, is NOT risk and is NOT an opportunity. EU STATE IS NOT ITALIAN MARKETABILITY.",
     "it": "LA SCADENZA DELL'APPROVAZIONE NON È UN MANCATO RINNOVO, NON è rischio e NON è opportunità. LO STATO EUROPEO NON È LA COMMERCIABILITÀ ITALIANA."
    },
    "NON_PROVA_COMMERCIALE": {
     "en": "does NOT prove channel demand, sell-in, sell-out, orders, inventory, margin, pipeline or purchase intent. Nothing here comes from ADAMA internal data. Agronomic pressure is an external commercial opportunity to examine — it is not demand.",
     "it": "NON prova domanda della distribuzione, sell-in, sell-out, ordine, scorte, margine, pipeline né intenzione d'acquisto. Nulla qui viene da dati interni ADAMA. La pressione agronomica è un'opportunità commerciale esterna da esaminare — non è domanda."
    },
    "PERCHE": {
     "en": "a European regulatory date is portfolio and supply preparation, not a field need. and none of the ADAMA products containing the substance is in the public commercial catalogue: the preparation is regulatory, not commercial.",
     "it": "una data regolatoria europea è preparazione di portafoglio e di supply, non necessità di campo. e nessuno dei prodotti ADAMA che contengono la sostanza è nel catalogo commerciale pubblico: la preparazione è regolatoria, non commerciale."
    },
