    "AUTORIDADE": "SCIENTIFICA",
    "CAIU_PORQUE": {
     "en": "the clause that looked most solid — bulletins from three regions — did not hold: the signal isolates damage on the bunch, and the source that states it once a year is not a bulletin but the annual session of a conference, whose transcript still has to be produced.",
     "it": "la clausola che sembrava piu solida — i bollettini di tre regioni — non ha retto: il segnale isola il danno sul grappolo, e la fonte che lo dichiara una volta l'anno non e un bollettino ma la sessione annuale di un convegno, con trascrizione da produrre."
    },
    "DECLARADA_PELO_AUTOR": "eseguibile con adattatore",
