    "AUTORIDADE": "UFFICIALE",
    "CAIU_PORQUE": {
     "en": "what looked like a trigger of change is, once made observable, a trigger of confirmation; and the primary source — the Servizio Fitosanitario of the Sicilian Region — has no record in the catalogue, so its access was never measured. UNKNOWN, not «it does not exist».",
     "it": "quello che sembrava un innesco di cambiamento è, una volta reso osservabile, un innesco di conferma; e la fonte primaria — il Servizio Fitosanitario della Regione Siciliana — non ha scheda nel catalogo, quindi il suo accesso non è mai stato misurato. NON SO, non «non esiste»."
    },
    "DECLARADA_PELO_AUTOR": "NON SO",
